//串行口中断服务程序
void Serial_Port( ) interrupt 4 using 0 {
if(TI) { // 如果TI=1，1个字节串行发送完毕
P1_0=1; // P1_0=1，允许74LS164并行输出，
//流水点亮二极管
SBUF=nSendByte; // 向SBUF写入数据，启动串行发送
delay(500); // 延时，点亮二极管持续一段时间
P1_0=0; // P1_0=0，允许向74LS164串行写入
nSendByte=nSendByte<<1; // 点亮数据左移1位
if(nSendByte==0)
nSendByte=1; //点亮数据是否左移8次？是，重新送点亮数据
SBUF=nSendByte; } // 向74LS164串行发送点亮数据
TI=0;
RI=0;
}

