// 串行口中断服务子程序
void Serial_Port() interrupt 4 using 0 {
if(P1_0==0) { // 如果P1_0=0表示开关K按下，
//可以读开关S0~S7的状态
P1_1=0; // P1_1=0并行读入开关的状态
delay(1);
P1_1=1; // P1_1=1将开关的状态串行读入到串口中
RI=0; //接收中断标志RI清0
nRxByte=SBUF;//接收的开关状态数据从SBUF读入到nRxByte
//单元中
P2=nRxByte; //开关状态数据送到P2口，驱动发光二极管发光
}
}

